/**
 * ============================================================================
 * CHORD SCHEDULING - Unified Appointment Scheduling Tool (v02)
 * ============================================================================
 * Consolidates: getApptSlots, getGroupedApptSlots, createAppt, createChildsAppt, cancelAppointment
 * 
 * Actions:
 *   - slots: Get available appointment slots
 *   - grouped_slots: Get slots for multiple patients booking together
 *   - book: Create/book an appointment
 *   - book_child: Create/book a parent's child's appointment
 *   - cancel: Cancel an existing appointment
 * ============================================================================
 */

const fetch = require('node-fetch');

// ============================================================================
// 📝 ACTION CONFIGURATIONS
// ============================================================================

const BASE_URL = 'https://c1-aicoe-nodered-lb.prod.c1conversations.io/FabricWorkflow/api/chord';

// ============================================================================
// ⚙️ DEFAULT VALUES CONFIGURATION
// ============================================================================
// Default values used when parameters are not provided
const DEFAULT_VALUES = {
    timeWindowMinutes: 60  // Default time window for grouped appointments (in minutes)
};

const ACTIONS = {
    slots: {
        endpoint: `${BASE_URL}/getApptSlots-dev`,
        method: 'POST',
        buildBody: (params, uui) => ({
            uui: uui,
            isNewPatient: params.isNewPatient,
            patientDob: params.patientDob,
            searchStartDate: params.searchStartDate
        }),
        validate: (params) => {
            if (isNullValue(params.isNewPatient)) {
                throw new Error("isNewPatient is required for 'slots' action");
            }
            if (isNullValue(params.patientDob)) {
                throw new Error("patientDob is required for 'slots' action");
            }
        },
        successLog: (data) => `Found ${data.totalSlots || (data.slots ? data.slots.length : 0) || 0} available slots`
    },
    grouped_slots: {
        endpoint: `${BASE_URL}/getGroupedApptSlots-dev`,
        method: 'POST',
        buildBody: (params, uui) => ({
            uui: uui,
            numberOfAppointments: params.numberOfPatients,
            timeWindowMinutes: params.timeWindowMinutes,
            isNewPatient: params.isNewPatient,
            patientDob: params.patientDob,
            searchStartDate: params.searchStartDate
        }),
        validate: (params) => {
            if (isNullValue(params.numberOfPatients)) {
                throw new Error("numberOfPatients is required for 'grouped_slots' action");
            }
            if (isNullValue(params.isNewPatient)) {
                throw new Error("isNewPatient is required for 'grouped_slots' action");
            }
            if (isNullValue(params.patientDob)) {
                throw new Error("patientDob is required for 'grouped_slots' action");
            }
            // timeWindowMinutes defaults to 60, so no validation needed
        },
        successLog: (data) => `Found ${data.totalGroups || (data.groups ? data.groups.length : 0) || 0} grouped slot options`
    },
    book: {
        endpoint: `${BASE_URL}/createAppt`,
        method: 'POST',
        buildBody: (params, uui) => ({
            uui: uui,
            patientId: params.patientId,
            apptTime: params.appointmentTime,
            operatoryId: params.operatoryId,
            apptDate: params.appointmentDate
        }),
        validate: (params) => {
            if (isNullValue(params.patientId)) throw new Error("patientId is required for 'book' action");
            if (isNullValue(params.appointmentDate)) throw new Error("appointmentDate is required for 'book' action");
            if (isNullValue(params.appointmentTime)) throw new Error("appointmentTime is required for 'book' action");
            if (isNullValue(params.operatoryId)) throw new Error("operatoryId is required for 'book' action");
        },
        successLog: () => 'Appointment booked successfully'
    },
    book_child: {
        endpoint: `${BASE_URL}/createChildAppt-dev`,
        method: 'POST',
        buildBody: (params, uui) => ({
            uui: uui,
            patientId: params.patientId, // Parent's Patient ID
            //phoneNumber: params.phoneNumber,
            childFirstName: params.childFirstName,
            childLastName: params.childLastName,
            childDateOfBirth: params.childDateOfBirth,
            apptTime: params.appointmentTime,
            operatoryId: params.operatoryId,
            apptDate: params.appointmentDate,
            isNewPatient: params.isNewPatient,
            patientDob: params.patientDob
        }),
        validate: (params) => {
            if (isNullValue(params.patientId)) throw new Error("patientId (parent/guardian) is required for 'book_child' action");
          /*  
          if (isNullValue(params.phoneNumber)) throw new Error("phoneNumber is required for 'book_child' action");
          */
            if (isNullValue(params.childFirstName)) throw new Error("childFirstName is required for 'book_child' action");
            if (isNullValue(params.childLastName)) throw new Error("childLastName is required for 'book_child' action");
            if (isNullValue(params.childDateOfBirth)) throw new Error("childDateOfBirth is required for 'book_child' action");
            if (isNullValue(params.appointmentDate)) throw new Error("appointmentDate is required for 'book_child' action");
            if (isNullValue(params.appointmentTime)) throw new Error("appointmentTime is required for 'book_child' action");
            if (isNullValue(params.operatoryId)) throw new Error("operatoryId is required for 'book_child' action");
        },
        successLog: () => 'Child\'s appointment booked successfully'
    },
    cancel: {
        endpoint: `${BASE_URL}/cancelAppt`,
        method: 'POST',
        buildBody: (params, uui) => ({
            appointmentId: params.appointmentId
        }),
        validate: (params) => {
            if (isNullValue(params.appointmentId)) {
                throw new Error("appointmentId is required for 'cancel' action");
            }
        },
        successLog: () => 'Appointment cancelled successfully'
    }
};

// ============================================================================
// 🔧 NULL VALUE HELPER
// ============================================================================
// Helper function to check if a value should be treated as null/empty
// "***" is used as an identifier for null values from Flowise tool calls
function isNullValue(value) {
    return value === null || 
           value === undefined || 
           value === '' || 
           value === '***' || 
           value === 'NULL' || 
           value === 'null' ||
           (typeof value === 'string' && value.trim() === '');
}

// ============================================================================
// 🔐 AUTHENTICATION
// ============================================================================

function getAuthHeader() {
    try {
        const username = "workflowapi";
        const password = "e^@V95&6sAJReTsb5!iq39mIC4HYIV";
        if (username && password) {
            const credentials = Buffer.from(`${username}:${password}`).toString('base64');
            return `Basic ${credentials}`;
        }
    } catch (e) {
        return null;
    }
    return null;
}

// ============================================================================
// 🔍 ERROR DETECTION HELPER
// ============================================================================

function checkForError(data) {
    if (!data || typeof data !== 'object') return null;

    // Check for various error patterns from backend
    // Pattern 1: { success: false, error: "..." }
    if (data.success === false) {
        return data.error || data.message || 'Operation failed';
    }

    // Pattern 2: { code: false, error: [...] } - Nexhealth API pattern
    if (data.code === false) {
        if (Array.isArray(data.error)) {
            return data.error.join(', ');
        }
        return data.error || data.message || 'API returned error';
    }

    // Pattern 3: String response containing error message
    if (typeof data === 'string' && data.toLowerCase().includes('failed')) {
        return data;
    }

    // Pattern 4: { error: "..." } without success/code field (but not valid response with error field)
    if (data.error && !data.data && !data.id && !data.slots && !data.groups && !data.appointments) {
        if (Array.isArray(data.error)) {
            return data.error.join(', ');
        }
        return data.error;
    }

    return null;
}

// ============================================================================
// 🚀 HTTP REQUEST ENGINE
// ============================================================================

async function executeRequest() {
    const toolName = 'chord_scheduling';
    const action = $action;
    const timeout = 30000;

    console.log(`[${toolName}] Action: ${action}`);

    // Validate action
    if (!action || !ACTIONS[action]) {
        const validActions = Object.keys(ACTIONS).join(', ');
        throw new Error(`Invalid action '${action}'. Valid actions: ${validActions}`);
    }

    const config = ACTIONS[action];

    // Get UUI with fallback
    let uui;
    if (!$vars || !$vars.c1mg_uui || $vars.c1mg_uui === 'c1mg_uui' || (typeof $vars.c1mg_uui === 'string' && $vars.c1mg_uui.trim() === '')) {
        uui = '767202758-000000000001105456-SR-000-000000000000DAL130-5DEAFCC2|77522|223076809|1767202758-000000000001105456-SR-000-000000000000DAL130-5DEAFCC2|junkVO|fdfee190-1e65-4c40-b512-1bb378dcdcab|FSV';
    } else {
        uui = $vars.c1mg_uui;
    }

    // Build params object from Flowise variables
    // Treat "***" as null (Flowise cannot reliably pass null through schema validation)
    // Safely access Flowise variables - wrap in try-catch to handle undefined variables
    const normalizeParam = (value) => {
        if (typeof value === 'undefined') return null;
        if (isNullValue(value)) return null;
        return value;
    };

    // Helper to safely get Flowise variable value without throwing if undefined
    const safeGetVar = (getter) => {
        try {
            return getter();
        } catch (e) {
            return undefined;
        }
    };

    const params = {
        numberOfPatients: normalizeParam(safeGetVar(() => typeof $numberOfPatients !== 'undefined' ? $numberOfPatients : undefined)),
        timeWindowMinutes: safeGetVar(() => {
            if (typeof $timeWindowMinutes !== 'undefined' && !isNullValue($timeWindowMinutes)) {
                return $timeWindowMinutes;
            }
            return DEFAULT_VALUES.timeWindowMinutes;
        }),
        patientId: normalizeParam(safeGetVar(() => typeof $patientId !== 'undefined' ? $patientId : undefined)),
        phoneNumber: normalizeParam(safeGetVar(() => typeof $phoneNumber !== 'undefined' ? $phoneNumber : undefined)),
        appointmentDate: normalizeParam(safeGetVar(() => typeof $appointmentDate !== 'undefined' ? $appointmentDate : undefined)),
        appointmentTime: normalizeParam(safeGetVar(() => typeof $appointmentTime !== 'undefined' ? $appointmentTime : undefined)),
        operatoryId: normalizeParam(safeGetVar(() => typeof $operatoryId !== 'undefined' ? $operatoryId : undefined)),
        appointmentId: normalizeParam(safeGetVar(() => typeof $appointmentId !== 'undefined' ? $appointmentId : undefined)),
        isNewPatient: normalizeParam(safeGetVar(() => typeof $isNewPatient !== 'undefined' ? $isNewPatient : undefined)),
        patientDob: normalizeParam(safeGetVar(() => typeof $patientDob !== 'undefined' ? $patientDob : undefined)),
        searchStartDate: normalizeParam(safeGetVar(() => typeof $searchStartDate !== 'undefined' ? $searchStartDate : undefined)),
        // Child-specific parameters
        childFirstName: normalizeParam(safeGetVar(() => typeof $childFirstName !== 'undefined' ? $childFirstName : undefined)),
        childLastName: normalizeParam(safeGetVar(() => typeof $childLastName !== 'undefined' ? $childLastName : undefined)),
        childDateOfBirth: normalizeParam(safeGetVar(() => typeof $childDateOfBirth !== 'undefined' ? $childDateOfBirth : undefined))
    };

    try {
        // Validate required params for this action
        config.validate(params);

        const body = config.buildBody(params, uui);
        console.log(`[${toolName}] Endpoint: ${config.method} ${config.endpoint}`);
        console.log(`[${toolName}] Request Body:`, JSON.stringify(body, null, 2));

        const headers = {
            'Content-Type': 'application/json'
        };

        const authHeader = getAuthHeader();
        if (authHeader) {
            headers['Authorization'] = authHeader;
        }

        const options = {
            method: config.method,
            headers: headers,
            body: JSON.stringify(body)
        };

        // Add timeout
        let timeoutId;
        if (typeof AbortController !== 'undefined') {
            const controller = new AbortController();
            timeoutId = setTimeout(() => controller.abort(), timeout);
            options.signal = controller.signal;
        }

        console.log(`[${toolName}] Making request...`);
        let response;
        try {
            response = await fetch(config.endpoint, options);
        } catch (fetchError) {
            // Handle network errors, connection failures, etc.
            console.error(`[${toolName}] Fetch error:`, fetchError);
            throw new Error(`Network error: Failed to connect to Node-RED endpoint. ${fetchError.message || 'Unknown network error'}`);
        }

        if (timeoutId) clearTimeout(timeoutId);

        console.log(`[${toolName}] Response Status: ${response.status} ${response.statusText}`);

        let data;
        try {
            const contentType = response.headers.get('content-type');
            if (contentType && contentType.includes('application/json')) {
                data = await response.json();
            } else {
                data = await response.text();
            }
        } catch (parseError) {
            console.error(`[${toolName}] Error parsing response:`, parseError);
            throw new Error(`Failed to parse response from Node-RED: ${parseError.message || 'Unknown parsing error'}`);
        }

        // Note: Empty responses are allowed - Node-RED may return empty responses
        // This will be handled gracefully by returning empty string or null

        // Check HTTP status
        if (!response.ok) {
            console.error(`[${toolName}] HTTP Error ${response.status}:`, data);
            // Try to extract error message from response body
            let errorMsg = `HTTP ${response.status}: ${response.statusText}`;
            if (data) {
                const bodyError = checkForError(typeof data === 'string' ? (() => { try { return JSON.parse(data); } catch(e) { return data; } })() : data);
                if (bodyError) errorMsg = bodyError;
            }
            throw new Error(errorMsg);
        }

        // Parse response if string
        let responseData = data;
        if (typeof data === 'string') {
            // Handle empty string responses
            if (data.trim() === '') {
                responseData = null;
            } else {
                try { 
                    responseData = JSON.parse(data); 
                } catch (e) { 
                    responseData = data; 
                }
            }
        }

        // Check for error patterns in successful HTTP response (only if responseData is not empty/null)
        if (responseData !== null && responseData !== undefined && responseData !== '') {
            const errorMessage = checkForError(responseData);
            if (errorMessage) {
                console.error(`[${toolName}] API Error:`, responseData);
                throw new Error(errorMessage);
            }
        }

        const successMsg = typeof config.successLog === 'function' ? config.successLog(responseData) : config.successLog;
        console.log(`[${toolName}] ${successMsg}`);

        // Return empty string or null gracefully if response is empty
        if (responseData === null || responseData === undefined) {
            return JSON.stringify({});
        }

        return JSON.stringify(responseData);

    } catch (error) {
        console.error(`[${toolName}] Error:`, error.message);
        console.error(`[${toolName}] Error stack:`, error.stack);
        console.error(`[${toolName}] Error details:`, {
            name: error.name,
            message: error.message,
            action: action,
            endpoint: config ? config.endpoint : 'unknown'
        });

        if (error.name === 'AbortError') {
            error.message = `Request timeout after ${timeout}ms. The Node-RED endpoint did not respond in time.`;
        }

        // If error message is empty or generic, provide more context
        let errorMessage = error.message || 'Unknown error occurred';
        if (!errorMessage || errorMessage.trim() === '') {
            errorMessage = `Failed to execute ${action} action. No error details available. Check Node-RED endpoint: ${config ? config.endpoint : 'unknown'}`;
        }

        const errorResponse = {
            error: `Failed to execute ${action}`,
            message: errorMessage,
            action: action,
            endpoint: config ? config.endpoint : 'unknown',
            timestamp: new Date().toISOString()
        };

        throw new Error(JSON.stringify(errorResponse, null, 2));
    }
}

return executeRequest();
